 /* Site-wide styles below. Vue custom elements have their own shadow-DOM styles,
    but content passed into their slots renders in the light DOM and is styled here. */
+
+@theme {
+    --color-paper: #f6f5ef;
+    --color-ink: #232c25;
+    --color-olive: #40563b;
+    --color-muted: #61675e;
+    --color-line: #d7d9ce;
+    --color-rust: #b05235;
+    --font-sans: "Segoe UI", Arial, sans-serif;
+    --font-serif: Georgia, "Times New Roman", serif;
+    --font-mono: Consolas, monospace;
+}
+
+:focus-visible { outline: 3px solid var(--color-rust); outline-offset: 5px; }
+::selection { background: #dce4d1; }
+.umb-block-grid__layout-container {
+    display: grid;
+    grid-template-columns: repeat(var(--umb-block-grid--grid-columns, 12), minmax(0, 1fr));
+}
+.umb-block-grid__layout-item {
+    grid-column: span var(--umb-block-grid--item-column-span, 12);
+    grid-row: span var(--umb-block-grid--item-row-span, 1);
+    min-width: 0;
+}
+.article-copy { font-size: 1.125rem; line-height: 1.85; color: var(--color-ink); }
+.article-copy p { margin-bottom: 1.5rem; }
+.article-copy h2 { font-family: var(--font-serif); font-size: clamp(1.7rem, 3vw, 2rem); line-height: 1.2; letter-spacing: -.025em; margin: 2.8rem 0 1rem; }
+.article-copy > :first-child { margin-top: 0; }
+.article-copy a { color: var(--color-olive); text-decoration: underline; text-underline-offset: 3px; }
