    var pageTitle = Model is BlogPost post ? post.Title ?? post.Name : siteName;
}
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <meta name="color-scheme" content="light" />
    <title>@pageTitle@(Model is BlogPost ? " | " + siteName : "")</title>
    @if (Model is BlogPost article)
    {
        <meta name="description" content="@article.Summary" />
    }
    <link rel="stylesheet" href="~/dist/site.css" asp-append-version="true" />
</head>
<body class="bg-paper font-sans text-ink antialiased">
    <a href="#main" class="sr-only focus:not-sr-only focus:fixed focus:left-4 focus:top-4 focus:z-50 focus:bg-white focus:p-4">Skip to content</a>
    <div class="mx-auto max-w-7xl px-6 md:px-10">
        <header class="flex items-center justify-between gap-4 border-b border-line py-7">
            <a href="@homeUrl" class="flex items-center gap-3 font-serif text-xl font-bold tracking-tight sm:text-2xl">
                <span class="flex h-9 w-9 items-center justify-center rounded-full bg-olive font-sans text-lg text-paper" aria-hidden="true">↗</span>
                @siteName
            </a>
            <nav aria-label="Main navigation">
                <a href="@(homeUrl + "#articles")" class="text-sm font-medium text-olive underline-offset-4 hover:underline">All stories <span aria-hidden="true">↗</span></a>
            </nav>
        </header>
        <main id="main" tabindex="-1">@RenderBody()</main>
        <footer class="flex flex-wrap items-center justify-between gap-5 border-t border-line py-8 text-sm text-muted">
            <a href="@homeUrl" class="font-serif text-lg text-ink">@siteName</a>
            <p>Ideas, tools, and the connections between them.</p>
            <a href="#main" class="text-olive hover:underline">Back to top ↑</a>
        </footer>
    </div>
</body>
</html>

