diff --git a/Umbraco.Bench.Umbraco/Views/Partials/blockgrid/Components/postListingBlock.cshtml b/Umbraco.Bench.Umbraco/Views/Partials/blockgrid/Components/postListingBlock.cshtml
new file mode 100644
