$pageHtml = Get-Content homepage-check.html -Raw -Encoding UTF8
$paths = @('/', '/one-protocol-more-possibilities/', '/from-conversation-to-published-content/', '/dist/site.css')
foreach ($path in $paths) { $status = curl.exe -k -s -o NUL -w '%{http_code}' ('https://localhost:44317' + $path); Write-Output ($path + ' ' + $status); if ($status -ne '200') { throw 'HTTP check failed' } }
$images = [regex]::Matches($pageHtml, '<img src="([^"]+)"')
foreach ($match in $images) { $src = [System.Net.WebUtility]::HtmlDecode($match.Groups[1].Value); $status = curl.exe -k -s -o NUL -w '%{http_code}' ('https://localhost:44317' + $src); Write-Output ('Image ' + $status); if ($status -ne '200') { throw 'Image check failed' } }

