@@ -0,0 +1,18 @@
+@model Umbraco.Bench.Umbraco.Models.Blocks.HeroModel
+<section class="grid items-center gap-10 py-12 md:grid-cols-2 md:gap-16 md:py-20">
+    <div>
+        <p class="mb-7 font-mono text-xs font-semibold tracking-widest text-olive">@Model.Eyebrow</p>
+        <h1 class="font-serif text-5xl leading-[1.04] tracking-tight text-ink sm:text-6xl lg:text-7xl">@Model.Heading</h1>
+        <div class="my-8 h-1 w-12 bg-rust" aria-hidden="true"></div>
+        <p class="max-w-lg text-lg leading-relaxed text-muted">@Model.Intro</p>
+    </div>
+    @if (!string.IsNullOrWhiteSpace(Model.ImageUrl))
+    {
+        <figure>
+            <div class="overflow-hidden rounded-t-[5rem] rounded-br-[5rem] bg-stone-200">
+                <img src="@Model.ImageUrl" alt="@Model.ImageAlt" width="1200" height="1000" fetchpriority="high" class="aspect-[6/5] w-full object-cover" />
+            </div>
+            <figcaption class="mt-3 text-right font-mono text-[10px] tracking-wide text-muted">@Model.ImageCredit</figcaption>
+        </figure>
+    }
+</section>
diff --git a/Umbraco.Bench.Umbraco/Views/Shared/Components/PostListing/Default.cshtml b/Umbraco.Bench.Umbraco/Views/Shared/Components/PostListing/Default.cshtml
new file mode 100644
index 0000000000000000000000000000000000000000..6e0c04d45bdf87d971211f46e2a757dd551cbdbf
--- /dev/null
+++ b/Umbraco.Bench.Umbraco/Views/Shared/Components/PostListing/Default.cshtml
@@ -0,0 +1,34 @@
+@model Umbraco.Bench.Umbraco.Models.Blocks.PostListingModel
+<section id="articles" class="scroll-mt-8 border-t border-line pb-20 pt-10">
+    <div class="mb-9 flex flex-wrap items-end justify-between gap-4">
+        <div>
+            <p class="mb-3 font-mono text-xs tracking-widest text-olive">THE LATEST</p>
+            <h2 class="font-serif text-3xl tracking-tight sm:text-4xl">@Model.Heading</h2>
+            <p class="mt-3 max-w-xl text-muted">@Model.Intro</p>
+        </div>
+        <span class="font-mono text-xs text-muted">@Model.Posts.Count.ToString("D2") STORIES</span>
+    </div>
+    <div class="grid gap-10 md:grid-cols-2">
+        @foreach (var post in Model.Posts)
+        {
+            <article class="group">
+                <a href="@post.Url" class="block rounded-sm" aria-label="@post.Title">
+                    @if (!string.IsNullOrWhiteSpace(post.ImageUrl))
+                    {
+                        <div class="mb-5 overflow-hidden rounded-sm bg-stone-200">
+                            <img src="@post.ImageUrl" alt="@post.ImageAlt" width="900" height="560" loading="lazy" class="aspect-[45/28] w-full object-cover transition-transform duration-300 motion-safe:group-hover:scale-105" />
+                        </div>
+                    }
+                    <p class="mb-3 font-mono text-xs tracking-wide text-muted"><time datetime="@post.Date.ToString("yyyy-MM-dd")">@post.Date.ToString("dd MMMM yyyy", System.Globalization.CultureInfo.GetCultureInfo("en-US"))</time> <span aria-hidden="true"> / </span> MCP</p>
+                    <h3 class="max-w-lg font-serif text-3xl leading-tight transition-colors group-hover:text-olive">@post.Title</h3>
+                    <p class="mt-3 max-w-lg leading-relaxed text-muted">@post.Summary</p>
+                    <span class="mt-5 inline-flex items-center gap-3 border-b border-olive pb-1 text-sm font-semibold text-olive">Read the story <span aria-hidden="true">↗</span></span>
+                </a>
+            </article>
+        }
+    </div>
+    @if (Model.Posts.Count == 0)
+    {
+        <p class="py-8 text-muted">New stories are on their way.</p>
+    }
+</section>
